/**
 * @summary Request mentorship from an alumni mentor
 */
export const createMentorshipRequestBodyMessageMin = 10;

export const CreateMentorshipRequestBody = zod.object({
  mentorName: zod.string(),
  mentorEmail: zod.string().email(),
  mentorField: zod.string().optional(),
  message: zod.string().min(createMentorshipRequestBodyMessageMin),
});

