/**
 * @summary Get AI university recommendations based on student profile
 */
export const AiRecommendBody = zod.object({}).passthrough();

export const AiRecommendResponse = zod.object({
  recommendations: zod
    .array(
      zod.object({
        universityId: zod.string(),
        matchScore: zod.number(),
        reasons: zod.array(zod.string()),
        concern: zod.string().nullish(),
        university: zod
          .object({
            id: zod.string(),
            name: zod.string(),
            country: zod.string(),
            city: zod.string(),
            ranking: zod.number().optional(),
            logoUrl: zod.string().optional(),
            imageUrl: zod.string().optional(),
            website: zod.string().optional(),
            description: zod.string().optional(),
            acceptanceRate: zod.number().optional(),
            avgTuitionUsd: zod.number().optional(),
            featured: zod.boolean().optional(),
            programCount: zod.number().optional(),
            createdAt: zod.coerce.date(),
          })
          .optional(),
      }),
    )
    .optional(),
});

